        min_edges_used = set()
        for i in range(n):
            if min_edges[i]:
                w, v = min_edges[i][0]
                if find(i) != find(v):
                    min_edges_used.add((i, v, w))
        if not min_edges_used:
            return -1
        for u, v, w in min_edges_used:
            if find(u) != find(v):
