                    if not mst_set[v]:
                        min_edges[u].append((w, u, v))

        # Find minimum edge for each component
        min_edges_for_component = []
        for u in range(n):
            if not mst_set[u]:
                if min_edges[u]:
                    min_edges_for_component.append(min(min_edges[u]))
                else:
                    min_edges_for_component.append(None)

        # Check if all components are connected
        all_connected = True
        for i in range(n):
            if not mst_set[i]:
                if min_edges_for_component[i] is None:
                    all_connected = False
                    break

        if all_connected:
            break

        # Add edges to MST
        for edge in min_edges_for_component:
            if edge is not None:
                w, u, v = edge
                if union(u, v):
                    total_cost += w
                    mst_set[u] = True
                    mst_set[v] = True

    # Check if all cities are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

    return total_cost
