def solve(n, roads):
    import heapq

    # Create adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Minimum spanning tree result
    mst_weight = 0
    mst_edges = set()

    # Union-Find (Disjoint Set Union) data structure
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        parent[root_v] = root_u
        return True

    # Boruvka's algorithm
    while True:
        # Initialize the minimum edge for each node
        min_edges = [None] * n
        for u in range(n):
            if not min_edges[u]:
                min_edges[u] = (float('inf'), -1)
            for v, w in graph[u]:
                if u < v:  # Avoid duplicate processing
                    if w < min_edges[u][0]:
                        min_edges[u] = (w, v)
                    if w < min_edges[v][0]:
                        min_edges[v] = (w, u)

        # Check if all nodes are connected
        all_connected = True
        for u in range(n):
            if min_edges[u][1] == -1:
                all_connected = False
                break

        if all_connected:
            break

        # Process edges
        added = False
        for u in range(n):
            if min_edges[u][1] != -1:
                v, w = min_edges[u][1], min_edges[u][0]
                if union(u, v):
                    mst_weight += w
                    added = True
        if not added:
            return -1

    # Check if all cities are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

    return mst_weight
