def solve(x):
    if x == 0:
        return 0
    # Initial guess using bit length
    guess = 1 << (x.bit_length() // 2)
    # Newton's method
    while True:
        next_guess = (guess + x // guess) // 2
        if next_guess >= guess:
            return guess
        guess = next_guess
```

