    if x < 2:
        return x
    # Initial guess using bit length to avoid division
    guess = 1 << (x.bit_length() // 2)
    while guess * guess > x:
        guess //= 2
    # Newton's method
    while True:
        next_guess = (guess + x // guess) // 2
        if next_guess >= guess:
            return guess
        guess = next_guess
