    if x < 0:
        return 0
    low = 0
    high = x
    while low <= high:
        mid = (low + high) // 2
        mid_sq = mid * mid
        if mid_sq == x:
            return mid
        elif mid_sq < x:
            low = mid + 1
        else:
            high = mid - 1
    return high
