        left, right = 0, len(sorted_nums)
        while left < right:
            mid = (left + right) // 2
            if sorted_nums[mid] < num:
                left = mid + 1
            else:
                right = mid
        return left

    sorted_nums = sorted(nums)
    result = 0
    for num in nums:
        result += count_less_than(num, sorted_nums)
    return result
