def solve(nums):
    def count_greater(nums, target):
        count = 0
        for num in nums:
            if num > target:
                count += 1
        return count

    nums_sorted = sorted(set(nums))
    num_to_rank = {num: i for i, num in enumerate(nums_sorted)}
    rank = [num_to_rank[num] for num in nums]
    n = len(nums)
    result = 0
    for i in range(n):
        result += n - 1 - rank[i]
    return result
```

