import bisect

def solve(nums):
    class SegmentTreeNode:
        def __init__(self, l, r):
            self.l = l
            self.r = r
            self.left = None
            self.right = None
            self.count = 0

    class SegmentTree:
        def __init__(self, data):
            self.data = data
            self.n = len(data)
            self.root = self.build(0, self.n - 1)

        def build(self, l, r):
            node = SegmentTreeNode(l, r)
            if l == r:
                return node
            mid = (l + r) // 2
            node.left = self.build(l, mid)
            node.right = self.build(mid + 1, r)
            return node

        def update(self, node, index, value):
            if node.l == node.r:
                node.count += value
                return
            if index <= node.left.r:
                self.update(node.left, index, value)
            else:
                self.update(node.right, index, value)
            node.count = node.left.count + node.right.count

        def query(self, node, l, r):
            if node.r < l or node.l > r:
                return 0
            if l <= node.l and node.r <= r:
                return node.count
            return self.query(node.left, l, r) + self.query(node.right, l, r)

    sorted_unique = sorted(set(nums))
    rank = {v: i + 1 for i, v in enumerate(sorted_unique)}
    compressed = [rank[num] for num in nums]

    tree = SegmentTree(compressed)
    res = 0
    for i in reversed(range(len(compressed))):
        res += tree.query(tree.root, 1, rank[nums[i]] - 1)
        tree.update(tree.root, rank[nums[i]], 1)
    return res
