from typing import List

def solve(nums: List[int]) -> List[List[int]]:
    if len(nums) == 1:
        return [nums]
    result = []
    for i in range(len(nums)):
        perm = [nums[i]]
        for j in range(i + 1, len(nums)):
            perm.append(nums[j])
        for p in solve(nums[:i] + nums[i + 1:j] + nums[j + 1:]):
            result.append(perm + p)
    return result

def partition(nums: List[int]) -> List[List[List[int]]]:
    if len(nums) <= 1:
        return [[nums]]
    result = []
    for i in range(len(nums)):
        part = [nums[i]]
        for j in range(i + 1, len(nums)):
            part.append(nums[j])
        for p in partition(nums[:i] + nums[i + 1:j] + nums[j + 1:]):
            result.append(part + p)
    return result

