```python
def generate_permutations(nums, start=0):
    if start == len(nums):
        return [nums[:]]
    result = []
    for i in range(start, len(nums)):
        nums[start], nums[i] = nums[i], nums[start]
        result += generate_permutations(nums, start+1)
        nums[start], nums[i] = nums[i], nums[start]
    return result

def solve(nums):
    return generate_permutations(nums)
