def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Prim's algorithm with array scan
    mst_set = [False] * n
    key = [float('inf')] * n
    parent = [-1] * n

    key[0] = 0
    min_heap = [(0, 0)]  # (key, node)

    while min_heap:
        weight, u = heapq.heappop(min_heap)
        if mst_set[u]:
            continue
        mst_set[u] = True
        for v, w in graph[u]:
            if not mst_set[v] and w < key[v]:
                key[v] = w
                parent[v] = u
                heapq.heappush(min_heap, (w, v))

    # Check if all nodes are included in MST
    if all(mst_set):
        return sum(key)
    else:
        return -1
