    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        parent[root_v] = root_u
        return True

    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((w, v))
        graph[v].append((w, u))

    mst_cost = 0
    total_edges = 0
    mst_edges = set()

    while total_edges < n - 1:
        min_edges = []
        for u in range(n):
            if graph[u]:
                min_edges.append((graph[u][0][0], u, graph[u][0][1]))
        if not min_edges:
            return -1
        min_edges.sort()
        selected = set()
        for w, u, v in min_edges:
            if find(u) != find(v):
                mst_cost += w
                union(u, v)
                mst_edges.add((u, v))
                total_edges += 1
                selected.add((u, v))
                selected.add((v, u))
        if total_edges == n - 1:
            break
        for u in range(n):
            graph[u] = [(w, v) for w, v in graph[u] if (u, v) not in selected or (v, u) not in selected]

    for u in range(n):
        if find(u) != find(0):
            return -1
    return mst_cost
