    edges.sort()

    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            mst_edges += 1
            if mst_edges == n - 1:
                break

    # Check if all nodes are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
