    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Find minimum spanning tree using Boruvka's algorithm
    def boruvka():
        parent = list(range(n))
        min_edges = [[] for _ in range(n)]
        total_weight = 0
        edges = []
        for u, v, w in roads:
            edges.append((w, u, v))
        edges.sort()

        while True:
            min_edges = [[] for _ in range(n)]
            for w, u, v in edges:
                if parent[u] != parent[v]:
                    min_edges[parent[u]].append((w, u, v))
                    min_edges[parent[v]].append((w, u, v))
            min_edge = None
            for i in range(n):
                if min_edges[i]:
                    min_edge = min(min_edges[i], key=lambda x: x[0])
                    break
            if not min_edge:
                break
            w, u, v = min_edge
            pu, pv = parent[u], parent[v]
            if pu == pv:
                continue
            total_weight += w
            for i in range(n):
                if parent[i] == pv:
                    parent[i] = pu

        # Check if all nodes are connected
        root = parent[0]
        for i in range(1, n):
            if parent[i] != root:
                return -1
        return total_weight

    return boruvka()
