    # Create adjacency list for each city
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Union-Find (Disjoint Set Union) data structure
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        parent[root_v] = root_u
        return True

    # Boruvka's algorithm
    total_cost = 0
    mst_set = set()
    mst_edges = []

    # List to store the minimum edge for each node
    min_edges = [None] * n

    # Initialize min_edges
    for i in range(n):
        for v, w in graph[i]:
            if min_edges[i] is None or w < min_edges[i][1]:
                min_edges[i] = (v, w)

    # Repeat until all nodes are included in MST
    while len(mst_set) < n:
        # Find the minimum edge for each node
        for i in range(n):
            if min_edges[i] is not None:
                u, w = min_edges[i]
                if find(i) != find(u):
                    mst_edges.append((i, u, w))

        # Select the minimum edge that connects two different components
        mst_edges.sort(key=lambda x: x[2])
        for u, v, w in mst_edges:
            if find(u) != find(v):
                union(u, v)
                total_cost += w
                mst_set.add(u)
                mst_set.add(v)
                # After adding the edge, update min_edges for the connected nodes
                for node in [u, v]:
                    for neighbor, weight in graph[node]:
                        if min_edges[node] is None or weight < min_edges[node][1]:
                            min_edges[node] = (neighbor, weight)
        mst_edges.clear()

    # Check if all nodes are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

