def solve(n, roads):
    import heapq

    # Create adjacency list for the graph
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Union-Find (Disjoint Set Union) data structure
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        parent[root_v] = root_u
        return True

    # Boruvka's algorithm
    total_cost = 0
    mst_set = [False] * n  # To track which nodes are in MST

    # Initialize minimum spanning tree
    for i in range(n):
        mst_set[i] = True

    # While not all nodes are in MST
    while not all(mst_set):
        # For each node, find the minimum edge to another node
        min_edges = [[] for _ in range(n)]
        for u in range(n):
            if not mst_set[u]:
                continue
            for v, w in graph[u]:
                if not mst_set[v]:
                    min_edges[v].append((w, u, v))

        # Find the minimum edge for each component
        min_edge = [None] * n
        for v in range(n):
            if not mst_set[v]:
                continue
            if min_edges[v]:
                min_edge[v] = min(min_edges[v])

        # Add the minimum edges to MST
        added = False
        for v in range(n):
            if not mst_set[v]:
                continue
            if min_edge[v]:
                w, u, v = min_edge[v]
                if not union(u, v):
                    continue
                total_cost += w
                mst_set[v] = False
                added = True

        if not added:
            return -1

    return total_cost
