def solve(nums):
    class SegmentTree:
        def __init__(self, size):
            self.n = 1
            while self.n < size:
                self.n <<= 1
            self.size = self.n
            self.tree = [0] * (2 * self.n)

        def update(self, pos, value):
            pos += self.n
            self.tree[pos] = value
            pos >>= 1
            while pos >= 1:
                left = self.tree[2 * pos]
                right = self.tree[2 * pos + 1]
                self.tree[pos] = left + right
                pos >>= 1

        def query(self, l, r):
            res = 0
            l += self.n
            r += self.n
            while l <= r:
                if l % 2 == 1:
                    res += self.tree[l]
                    l += 1
                if r % 2 == 0:
                    res += self.tree[r]
                    r -= 1
                l >>= 1
                r >>= 1
            return res

    def count_inversion(nums):
        unique = sorted(set(nums))
        mapping = {v: i for i, v in enumerate(unique)}
        size = len(unique)
        st = SegmentTree(size)
        count = 0
        for i in reversed(range(len(nums))):
            pos = mapping[nums[i]]
            count += st.query(0, pos - 1)
            st.update(pos, 1)
        return count

    return count_inversion(nums)
