        def __init__(self, size):
            self.n = 1
            while self.n < size:
                self.n <<= 1
            self.tree = [0] * (2 * self.n)

        def update(self, pos, value):
            pos += self.n
            self.tree[pos] = value
            pos >>= 1
            while pos >= 1:
                self.tree[pos] = self.tree[2 * pos] + self.tree[2 * pos + 1]
                pos >>= 1

        def query(self, l, r):
            res = 0
            l += self.n
            r += self.n
            while l <= r:
                if l % 2 == 1:
                    res += self.tree[l]
                    l += 1
                if r % 2 == 0:
                    res += self.tree[r]
                    r -= 1
                l >>= 1
                r >>= 1
            return res

    sorted_unique = sorted(set(nums))
    rank = {v: i for i, v in enumerate(sorted_unique)}
    max_rank = len(sorted_unique)

    st = SegmentTree(max_rank)

    count = 0
    for num in reversed(nums):
        r = rank[num]
        count += st.query(0, r - 1)
        st.update(r, 1)

    return count
