def solve(s, t):
    import bisect
    if not s:
        return True
    if not t:
        return False

    # Preprocess the positions of each character in t
    pos = {}
    for i, char in enumerate(t):
        if char not in pos:
            pos[char] = []
        pos[char].append(i)

    # Check if all characters in s are in t
    for char in s:
        if char not in pos:
            return False

    # Use binary search to check if the characters in s appear in order in t
    current_pos = -1
    for char in s:
        # Find the first occurrence of char in t after current_pos
        idx_list = pos[char]
        i = bisect.bisect_right(idx_list, current_pos)
        if i == len(idx_list):
            return False
        current_pos = idx_list[i]

    return True
