def solve(s, t):
    if not s:
        return True
    if not t:
        return False

    s_len = len(s)
    t_len = len(t)

    # Find the indices of characters in t that match the order in s
    indices = []
    for char in s:
        found = False
        for i in range(len(indices), t_len):
            if t[i] == char:
                indices.append(i)
                found = True
                break
        if not found:
            return False

    # Check if the sequence of indices is in increasing order
    for i in range(1, s_len):
        if indices[i] <= indices[i - 1]:
            return False

    return True
```

