def solve(s: str, t: str) -> bool:
    if not s:
        return True
    i = 0  # pointer for s
    j = 0  # pointer for t
    len_s, len_t = len(s), len(t)
    if len_s > len_t:
        return False
    while j < len_t:
        if t[j] == s[i]:
            i += 1
            if i == len_s:
                return True
        j += 1
    return False
