from collections import deque

def solve(s, t):
    def is_subsequence(s, t):
        if not s:
            return True
        if not t:
            return False
        i = 0
        for char in t:
            if char == s[i]:
                i += 1
                if i == len(s):
                    return True
        return False

    def remove_chars(s, t):
        if not s:
            return t
        if not t:
            return s
        i = 0
        j = 0
        result = []
        while i < len(s) and j < len(t):
            if s[i] == t[j]:
                result.append(s[i])
                i += 1
            j += 1
        return ''.join(result)

    def get_interleaved(s, t):
        if not s:
            return t
        if not t:
            return s
        i = 0
        j = 0
        result = []
        while i < len(s) and j < len(t):
            if s[i] == t[j]:
                result.append(s[i])
                i += 1
            j += 1
        if i < len(s):
            result.append(s[i:])
        return ''.join(result)

    if not s:
        return True
    if not t:
        return False
    if len(s) > len(t):
        return False

    s_list = list(s)
    t_list = list(t)

    s_queue = deque(s_list)
    t_queue = deque(t_list)

    while s_queue and t_queue:
        if s_queue[0] == t_queue[0]:
            s_queue.popleft()
        t_queue.popleft()

    return not s_queue
```

