from collections import deque

def solve(s, t):
    def check_sequence(s, t, index_s, index_t):
        if index_s == len(s):
            return True
        if index_t == len(t):
            return False
        if s[index_s] == t[index_t]:
            return check_sequence(s, t, index_s + 1, index_t + 1)
        else:
            return check_sequence(s, t, index_s, index_t + 1)

    def is_valid_sequence(s, t):
        if len(s) > len(t):
            return False
        if not s:
            return True
        return check_sequence(s, t, 0, 0)

    def delete_characters(t, s):
        if not s:
            return t
        i = 0
        j = 0
        result = []
        while i < len(t) and j < len(s):
            if t[i] == s[j]:
                result.append(t[i])
                j += 1
            i += 1
        return ''.join(result)

    if len(s) > len(t):
        return False
    if not s:
        return True
    filtered = delete_characters(t, s)
    return filtered == s
```

