from collections import deque

def solve(s, t):
    if not s:
        return True
    if not t:
        return False

    def is_subsequence(s, t):
        t_deque = deque(t)
        for char in s:
            found = False
            while t_deque:
                if t_deque[0] == char:
                    t_deque.popleft()
                    found = True
                    break
                else:
                    t_deque.popleft()
            if not found:
                return False
        return True

    return is_subsequence(s, t)
