def solve(nums):
    result = []
    n = len(nums)

    def backtrack(path):
        if len(path) == n:
            result.append(path[:])
            return
        for i in range(n):
            if i not in path:
                path.append(i)
                backtrack(path)
                path.pop()

    backtrack([])
    return [[nums[i] for i in perm] for perm in result]
