def solve(nums):
    from copy import copy

    def permute(arr, start, end, result):
        if start == end:
            result.append(copy(arr))
        else:
            for i in range(start, end):
                arr[start], arr[i] = arr[i], arr[start]
                permute(arr, start + 1, end, result)
                arr[start], arr[i] = arr[i], arr[start]

    result = []
    permute(nums, 0, len(nums), result)
    return result
