def solve(s, t):
    import bisect
    if not s:
        return True
    if not t:
        return False

    # Create a list of indices for each character in t
    char_indices = {}
    for idx, char in enumerate(t):
        if char not in char_indices:
            char_indices[char] = []
        char_indices[char].append(idx)

    # Check if all characters in s exist in t
    for char in s:
        if char not in char_indices:
            return False

    # Use binary search to check if characters in s appear in order
    prev_pos = -1
    for char in s:
        indices = char_indices[char]
        # Find the first index in indices that is after prev_pos
        i = bisect.bisect_right(indices, prev_pos)
        if i == len(indices):
            return False
        prev_pos = indices[i]

    return True
```

