def solve(s, t):
    if len(s) == 0:
        return True
    if len(t) < len(s):
        return False
    i = 0  # pointer for s
    j = 0  # pointer for t
    while j < len(t):
        if t[j] == s[i]:
            i += 1
            if i == len(s):
                return True
        j += 1
    return False
```

