import sys
sys.setrecursionlimit(10000)

def solve(s, t):
    if not s:
        return True
    if not t:
        return False

    # Check if the first character matches
    if s[0] == t[0]:
        # Check the rest of the string recursively
        if solve(s[1:], t[1:]):
            return True

    # If not, check if the first character of t is in the rest of t
