def solve(s, t):
    import itertools

    # Check if s is empty, which is a valid case
    if not s:
        return True

    # Check if t is empty but s is not, which is invalid
    if not t:
        return False

    # Find the positions of the first character of s in t
    first_char_pos = [i for i, c in enumerate(t) if c == s[0]]
    if not first_char_pos:
        return False

    # Iterate through the positions of the first character and check if the rest of the characters of s match in order
    for start in first_char_pos:
        match = True
        for i in range(1, len(s)):
            try:
                # Find the next occurrence of s[i] in t after the previous position
                pos = t.index(s[i], start + 1)
                start = pos
            except ValueError:
                match = False
                break
        if match:
            return True

    return False
