        result = []
        index = 0
        for char in chars:
            found = False
            for i in range(index, len(t)):
                if t[i] == char:
                    result.append(i)
                    index = i + 1
                    found = True
                    break
            if not found:
                return None
        return result

    def check_positions(s_indices, t_indices):
        if len(s_indices) != len(t_indices):
            return False
        for i in range(len(s_indices)):
            if s_indices[i] > t_indices[i]:
                return False
        return True

    if not s:
        return True

    s_indices = list(range(len(s)))
    t_indices = get_chars_in_order(t, s)
    if t_indices is None:
        return False

    return check_positions(s_indices, t_indices)
