def solve(nums):
    # If the list has less than 3 elements, any index is a valid peak
    if len(nums) < 3:
        return 0

    # Check if the middle element is greater than its neighbors
    mid = len(nums) // 2
    if nums[mid] > nums[mid - 1] and nums[mid] > nums[mid + 1]:
        return mid

    # If the middle element is not a peak, search the left half
    if nums[mid] < nums[mid - 1]:
        return solve(nums[:mid])

    # Otherwise, search the right half
    return solve(nums[mid + 1:])
```

