    left = 0
    right = len(nums) - 1

    while left < right:
        mid = (left + right) // 2
        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid

    # Check if left is a peak
    if left == 0:
        return 0
    if left == len(nums) - 1:
        return len(nums) - 1
    if nums[left] > nums[left - 1] and nums[left] > nums[left + 1]:
        return left
    # If left is not a peak, check left-1 or left+1
    if nums[left - 1] > nums[left] and nums[left - 1] > nums[left + 1]:
        return left - 1
    return left + 1
