def solve(nums):
    def backtrack(path, used):
        if len(path) == len(nums):
            return [path.copy()]
        res = []
        for i in range(len(nums)):
            if not used[i]:
                used[i] = True
                path.append(nums[i])
                res.extend(backtrack(path, used))
                path.pop()
                used[i] = False
        return res

    used = [False] * len(nums)
    return backtrack([], used)
