    # Merge the two sorted lists using two pointers
    i = j = 0
    result = []
    while i < m and j < n:
        if nums1[i] <= nums2[j]:
            result.append(nums1[i])
            i += 1
        else:
            result.append(nums2[j])
            j += 1
    # Add remaining elements from nums1 and nums2
    while i < m:
        result.append(nums1[i])
        i += 1
    while j < n:
        result.append(nums2[j])
        j += 1
    # Update nums1 with the merged result
    for idx in range(len(nums1)):
        nums1[idx] = result[idx]
