class Solution {
    public int minDeletions(String s) {
        int n=s.length();
        int arr[]=new int[26];
        for(int i=0;i<s.length();i++)
        {
            char ch=s.charAt(i);
            arr[ch-\'a\']++;
        }
        PriorityQueue<Integer> pr=new PriorityQueue<>(Collections.reverseOrder());
        for(int a:arr)
        {
            if(a!=0)
              pr.add(a);
           //System.out.println(a+" "+pr.peek());
        }
        int delet=0;
        while(pr.size()>1)
        {
            int x=pr.poll();
            //System.out.println(x+"  "+pr.peek());
            if(pr.peek()!=null &&  pr.peek()==x) 
            {
                pr.add((x-1)>=0?(x-1):0);
                delet++;
            }
        }
        return delet;

    }
}
