def solve(n, roads):
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu == pv:
            return False
        parent[pu] = pv
        return True

    total_cost = 0
    count = 0

    for u, v, w in roads:
        if union(u, v):
            total_cost += w
            count += 1
            if count == n - 1:
                break

    if count < n - 1:
        return -1
    return total_cost
```

