def solve(n, roads):
    import heapq

    def mst_cost(n, roads):
        graph = [[] for _ in range(n)]
        for u, v, w in roads:
            graph[u].append((v, w))
            graph[v].append((u, w))

        visited = [False] * n
        total_cost = 0
        heap = [(0, 0)]  # (cost, node)

        while heap:
            cost, node = heapq.heappop(heap)
            if visited[node]:
                continue
            visited[node] = True
            total_cost += cost
            for neighbor, weight in graph[node]:
                if not visited[neighbor]:
                    heapq.heappush(heap, (weight, neighbor))
        return total_cost if all(visited) else -1

    return mst_cost(n, roads)
```

