def solve(n, roads):
    import heapq

    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        root_x = find(parent, x)
        root_y = find(parent, y)
        if root_x == root_y:
            return False
        if rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        else:
            parent[root_y] = root_x
            if rank[root_x] == rank[root_y]:
                rank[root_x] += 1
        return True

    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    edges = []
    for u in range(n):
        for v, w in graph[u]:
            if u < v:
                edges.append((w, u, v))

    heapq.heapify(edges)

    parent = [i for i in range(n)]
    rank = [1] * n
    total_cost = 0
    count = 0

    while edges:
        w, u, v = heapq.heappop(edges)
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            total_cost += w
            count += 1
            if count == n - 1:
                break

    root = find(parent, 0)
    for i in range(1, n):
        if find(parent, i) != root:
            return -1

    return total_cost
```

