        return parent[x]

    def union(parent, rank, x, y):
        root_x = find(parent, x)
        root_y = find(parent, y)
        if root_x != root_y:
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                if rank[root_x] == rank[root_y]:
                    rank[root_x] += 1
            return True
        return False

    # Sort roads by cost in ascending order
    roads.sort(key=lambda x: x[2])

    # Initialize parent and rank arrays for union-find
    parent = list(range(n))
    rank = [1] * n

    total_cost = 0
    count = 0

    for u, v, w in roads:
        if union(parent, rank, u, v):
            total_cost += w
            count += 1
            if count == n - 1:
                break

    # If all cities are connected, return total cost, else -1
    return total_cost if count == n - 1 else -1
