import sys

def solve(n, roads):
    import heapq

    # Create adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Kruskal's algorithm implementation
    def kruskal():
        parent = list(range(n))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u
        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return False
            parent[root_v] = root_u
            return True

        # Sort edges by weight
        edges = []
        for u in range(n):
            for v, w in graph[u]:
                if u < v:  # avoid duplicates
                    edges.append((w, u, v))
        edges.sort()

        total_cost = 0
        count = 0
        for w, u, v in edges:
            if union(u, v):
                total_cost += w
                count += 1
                if count == n - 1:
                    return total_cost
        return -1

    # Check if the graph is disconnected
    def is_connected():
        visited = [False] * n
        stack = [0]
        visited[0] = True
        while stack:
            u = stack.pop()
            for v, _ in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        return all(visited)

    if not is_connected():
        return -1

    return kruskal()
