def solve(nums):
    from collections import defaultdict

    count = defaultdict(int)
    for num in nums:
        count[num] += 1

    result = 0
    nums_unique = sorted(count.keys())
    for i in range(len(nums_unique)):
        for j in range(i + 1, len(nums_unique)):
            if nums_unique[i] < nums_unique[j]:
                result += count[nums_unique[i]] * count[nums_unique[j]]
            elif nums_unique[i] > nums_unique[j]:
                result += count[nums_unique[j]] * count[nums_unique[i]]

    return result
```

