def solve(nums):
    def count_less_than(nums, target):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    nums_sorted = sorted(nums)
    result = 0
    for i in range(len(nums)):
        target = nums[i]
        pos = count_less_than(nums_sorted, target)
        result += pos
    return result
```

