from collections import defaultdict

def solve(nums):
    graph = defaultdict(list)
    for i, num in enumerate(nums):
        graph[num].append(i)

    result = []
    visited = set()

    def dfs(node, path):
        if node in visited:
            return
        visited.add(node)
        result.append(path + [node])
        for neighbor in graph[node]:
            dfs(neighbor, path + [node])

    for num in nums:
        if num not in visited:
            dfs(num, [])

    return result
```

