import sys
import math

def solve(n, roads):
    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)
        if xroot == yroot:
            return
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        else:
            parent[yroot] = xroot
            if rank[xroot] == rank[yroot]:
                rank[xroot] += 1

    # Build the graph
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Kruskal's algorithm implementation
    edges = []
    for i in range(n):
        for v, w in graph[i]:
            if i < v:  # avoid duplicates
                edges.append((w, i, v))

    edges.sort()
    parent = list(range(n))
    rank = [1] * n
    mst_weight = 0
    edges_used = 0

    for w, u, v in edges:
        root_u = find(parent, u)
        root_v = find(parent, v)
        if root_u != root_v:
            union(parent, rank, root_u, root_v)
            mst_weight += w
            edges_used += 1
            if edges_used == n - 1:
                break

    # Check if all nodes are connected
    root = find(parent, 0)
    for i in range(1, n):
        if find(parent, i) != root:
            return -1

    return mst_weight
