import sys
import heapq

def solve(n, roads):
    INF = float('inf')
    adj = [[] for _ in range(n)]

    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))

    def dijkstra(start):
        dist = [INF] * n
        dist[start] = 0
        heap = [(0, start)]

        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    min_total = INF
    for i in range(n):
        dist = dijkstra(i)
        total = sum(dist)
        if total < min_total:
            min_total = total

    return min_total if min_total != INF else -1
