import heapq

def solve(points, k):
    def distance_squared(point):
        return point[0] ** 2 + point[1] ** 2

    # Use a max-heap to keep the k smallest elements
    # Since Python's heapq is a min-heap, we store negative distances
    heap = []
    for point in points:
        dist = distance_squared(point)
        if len(heap) < k:
            heapq.heappush(heap, (-dist, point))
        else:
            # If the current point is closer than the farthest in the heap
            if dist < -heap[0][0]:
                heapq.heappushpop(heap, (-dist, point))

    # Extract the points from the heap
    return [point for (dist, point) in heap]
