    def solve(self, points: List[List[int]], k: int) -> List[List[int]]:
        def distance_squared(point):
            return point[0]**2 + point[1]**2

        def get_key(point):
            return distance_squared(point)

        points.sort(key=get_key)
        return points[:k]
```

