def solve(nums1, m, nums2, n):
    def swap(i, j):
        nums1[i], nums1[j] = nums1[j], nums1[i]

    def move_to_end(i):
        while i < m + n and nums1[i] != 0:
            i += 1
        if i < m + n:
            swap(i, m + n - 1)

    i = m + n - 1
    j = m - 1
    while i >= 0 and j >= 0:
        if nums1[j] > nums2[i]:
            swap(j, i)
            i -= 1
        else:
            j -= 1
    while i >= 0:
        move_to_end(i)
        i -= 1
