def solve(x):
    if x < 0:
        raise ValueError("Input must be non-negative")
    if x == 0:
        return 0
    low = 0
    high = x
    while low <= high:
        mid = (low + high) // 2
        mid_squared = mid * mid
        if mid_squared == x:
            return mid
        elif mid_squared < x:
            low = mid + 1
        else:
            high = mid - 1
    return high
```

