def solve(nums):
    def count_inversion(start, end):
        if start >= end:
            return 0
        mid = (start + end) // 2
        left = count_inversion(start, mid)
        right = count_inversion(mid + 1, end)
        i = start
        j = mid + 1
        temp = []
        inv_count = 0
        while i <= mid and j <= end:
            if nums[i] <= nums[j]:
                temp.append(nums[i])
                i += 1
            else:
                temp.append(nums[j])
                inv_count += (mid - i + 1)
                j += 1
        while i <= mid:
            temp.append(nums[i])
            i += 1
        while j <= end:
            temp.append(nums[j])
            j += 1
        for k in range(len(temp)):
            nums[start + k] = temp[k]
        return left + right + inv_count

    return count_inversion(0, len(nums) - 1)
