def solve(nums):
    def count_inversions(arr):
        def merge_sort(arr):
            if len(arr) <= 1:
                return arr, 0
            mid = len(arr) // 2
            left, left_count = merge_sort(arr[:mid])
            right, right_count = merge_sort(arr[mid:])
            merged, split_count = merge(left, right)
            return merged, left_count + right_count + split_count

        def merge(left, right):
            merged = []
            i = j = 0
            count = 0
            while i < len(left) and j < len(right):
                if left[i] <= right[j]:
                    merged.append(left[i])
                    i += 1
                else:
                    merged.append(right[j])
                    count += len(left) - i
                    j += 1
            merged += left[i:]
            merged += right[j:]
            return merged, count

        _, total = merge_sort(arr)
        return total

    return count_inversions(nums)
```

