def solve(n, roads):
    import heapq

    # Initialize the minimum spanning tree (MST) with 0 cost
    mst_cost = 0
    # Set to keep track of visited cities
    visited = set()
    # Priority queue (min-heap) to store edges
    heap = []

    # Start with city 0
    heapq.heappush(heap, (0, 0))  # (cost, city)

    while heap:
        cost, city = heapq.heappop(heap)
        if city in visited:
            continue
        visited.add(city)
        mst_cost += cost

        for road in roads:
            u, v, w = road
            if city == u:
                if v not in visited:
                    heapq.heappush(heap, (w, v))
            elif city == v:
                if u not in visited:
                    heapq.heappush(heap, (w, u))

    # Check if all cities are visited
    if len(visited) != n:
        return -1

    return mst_cost
