    def count_inversion_pairs(arr):
        if len(arr) <= 1:
            return 0
        mid = len(arr) // 2
        left = arr[:mid]
        right = arr[mid:]
        return count_inversion_pairs(left) + count_inversion_pairs(right) + merge_and_count(left, right)

    def merge_and_count(left, right):
        merged = []
        i = j = inv_count = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
                inv_count += len(left) - i
        merged.extend(left[i:])
        merged.extend(right[j:])
        return inv_count

    return count_inversion_pairs(nums)
