        if l >= r:
            return 0
        mid = (l + r) // 2
        left_count = count_inversion(arr, l, mid)
        right_count = count_inversion(arr, mid + 1, r)
        merge_count = merge(arr, l, mid, r)
        return left_count + right_count + merge_count

    def merge(arr, l, mid, r):
        temp = []
        i = l
        j = mid + 1
        inv_count = 0
        while i <= mid and j <= r:
            if arr[i] <= arr[j]:
                temp.append(arr[i])
                i += 1
            else:
                temp.append(arr[j])
                inv_count += (mid - i + 1)
                j += 1
        while i <= mid:
            temp.append(arr[i])
            i += 1
        while j <= r:
            temp.append(arr[j])
            j += 1
        for k in range(len(temp)):
            arr[l + k] = temp[k]
        return inv_count

    return count_inversion(nums, 0, len(nums) - 1)
