def solve(nums):
    from bisect import bisect_right, bisect_left

    # Coordinate compression
    sorted_unique = sorted(set(nums))
    compress = {v: i for i, v in enumerate(sorted_unique)}
    n = len(sorted_unique)
    compressed = [compress[num] for num in nums]

    # Fenwick Tree (Binary Indexed Tree)
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, idx, delta=1):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    ft = FenwickTree(n)
    count = 0
    for i in reversed(range(len(compressed))):
        count += ft.query(compressed[i])
        ft.update(compressed[i] + 1)
    return count
```

