def solve(nums):
    def count_pairs(arr, left, right, val):
        mid = (left + right) // 2
        if arr[mid] == val:
            return count_pairs(arr, left, mid, val) + count_pairs(arr, mid + 1, right, val)
        elif arr[mid] < val:
            return count_pairs(arr, mid + 1, right, val)
        else:
            return count_pairs(arr, left, mid, val)

    nums.sort()
    count = 0
    for i in range(len(nums)):
        count += count_pairs(nums, i + 1, len(nums) - 1, nums[i])
    return count
```

