def solve(nums):
    def backtrack(path):
        if not path:
            yield []
            yield [path]
        else:
            yield []
            yield [path]
            for i in range(len(path)):
                yield from backtrack(path[i:])

    result = []
    for i in range(len(nums)):
        for subset in backtrack(nums[i:]):
            result.append(subset)
    return result
