def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Kruskal's algorithm
    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        root_x = find(parent, x)
        root_y = find(parent, y)
        if root_x == root_y:
            return False
        if rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        else:
            parent[root_y] = root_x
            if rank[root_x] == rank[root_y]:
                rank[root_x] += 1
        return True

    # Sort roads by weight
    roads.sort(key=lambda x: x[2])

    parent = list(range(n))
    rank = [1] * n
    total_cost = 0
    edges_used = 0

    for u, v, w in roads:
        if union(parent, rank, u, v):
            total_cost += w
            edges_used += 1
            if edges_used == n - 1:
                break

    # Check if all cities are connected
    root = find(parent, 0)
    for i in range(1, n):
        if find(parent, i) != root:
            return -1

    return total_cost
