                rank[root_u] += 1
        return True

    # Use Prim's algorithm to find MST
    visited = [False] * n
    min_heap = [(0, 0)]  # (cost, node)
    total_cost = 0

    while min_heap:
        cost, u = heapq.heappop(min_heap)
        if visited[u]:
            continue
        visited[u] = True
        total_cost += cost
        for v, w in roads:
            if u == v:
                continue
            if not visited[v]:
                heapq.heappush(min_heap, (w, v))

    # Check if all cities are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1
    return total_cost
```

