def solve(nums):
    def count_pairs(start, end, sorted_nums):
        count = 0
        for i in range(start, end):
            val = nums[i]
            left, right = start, end
            while left < right:
                mid = (left + right) // 2
                if sorted_nums[mid] < val:
                    left = mid + 1
                else:
                    right = mid
            count += left - start
        return count

    n = len(nums)
    result = 0
    for i in range(n):
        result += count_pairs(i + 1, n, nums[i + 1:])
    return result
```

